window.WIRD_SITE = {"reader":{"words":[{"ar":"بِسْمِ","tr":"bis'mi","gl":"In (the) name","glFr":"Au nom","a":1,"r":"سمو","lemma":"ٱسْم"},{"ar":"ٱللَّهِ","tr":"l-lahi","gl":"(of) Allah","glFr":"d'Allah","a":1,"r":"أله","lemma":"ٱللَّه"},{"ar":"ٱلرَّحْمَـٰنِ","tr":"l-raḥmāni","gl":"the Most Gracious","glFr":"le Tout Miséricordieux","a":1,"r":"رحم","lemma":"رَّحْمَٰن"},{"ar":"ٱلرَّحِيمِ","tr":"l-raḥīmi","gl":"the Most Merciful","glFr":"le Très Miséricordieux","a":1,"r":"رحم","lemma":"رَّحِيم"},{"ar":"ٱلْحَمْدُ","tr":"al-ḥamdu","gl":"All praises and thanks","glFr":"Louange","a":2,"r":"حمد","lemma":"حَمْد"},{"ar":"لِلَّهِ","tr":"lillahi","gl":"(be) to Allah","glFr":"à Allah","a":2,"r":"أله","lemma":"ٱللَّه"},{"ar":"رَبِّ","tr":"rabbi","gl":"the Lord","glFr":"Seigneur","a":2,"r":"ربب","lemma":"رَبّ"},{"ar":"ٱلْعَـٰلَمِينَ","tr":"l-ʿālamīna","gl":"of the universe","glFr":"de l'univers","a":2,"r":"علم","lemma":"عَٰلَمِين"},{"ar":"ٱلرَّحْمَـٰنِ","tr":"al-raḥmāni","gl":"The Most Gracious","glFr":"Le Tout Miséricordieux","a":3,"r":"رحم","lemma":"رَّحْمَٰن"},{"ar":"ٱلرَّحِيمِ","tr":"l-raḥīmi","gl":"the Most Merciful","glFr":"le Très Miséricordieux","a":3,"r":"رحم","lemma":"رَّحِيم"},{"ar":"مَـٰلِكِ","tr":"māliki","gl":"(The) Master","glFr":"Maître","a":4,"r":"ملك","lemma":"مَٰلِك"},{"ar":"يَوْمِ","tr":"yawmi","gl":"(of the) Day","glFr":"du Jour","a":4,"r":"يوم","lemma":"يَوْم"},{"ar":"ٱلدِّينِ","tr":"l-dīni","gl":"(of the) Judgment","glFr":"de la Rétribution","a":4,"r":"دين","lemma":"دِين"},{"ar":"إِيَّاكَ","tr":"iyyāka","gl":"You Alone","glFr":"Toi [Seul]","a":5,"r":null,"lemma":null},{"ar":"نَعْبُدُ","tr":"naʿbudu","gl":"we worship","glFr":"nous adorons","a":5,"r":"عبد","lemma":"عَبَدَ"},{"ar":"وَإِيَّاكَ","tr":"wa-iyyāka","gl":"and You Alone","glFr":"et Toi [Seul]","a":5,"r":null,"lemma":null},{"ar":"نَسْتَعِينُ","tr":"nastaʿīnu","gl":"we ask for help","glFr":"nous implorons secours","a":5,"r":"عون","lemma":"ٱسْتَعِينُ"},{"ar":"ٱهْدِنَا","tr":"ih'dinā","gl":"Guide us","glFr":"Guide-nous","a":6,"r":"هدي","lemma":"هَدَى"},{"ar":"ٱلصِّرَٰطَ","tr":"l-ṣirāṭa","gl":"(to) the path","glFr":"dans le chemin","a":6,"r":"صرط","lemma":"صِرَٰط"},{"ar":"ٱلْمُسْتَقِيمَ","tr":"l-mus'taqīma","gl":"the straight","glFr":"le droit","a":6,"r":"قوم","lemma":"مُّسْتَقِيم"},{"ar":"صِرَٰطَ","tr":"ṣirāṭa","gl":"(The) path","glFr":"Le chemin","a":7,"r":"صرط","lemma":"صِرَٰط"},{"ar":"ٱلَّذِينَ","tr":"alladhīna","gl":"(of) those","glFr":"de ceux","a":7,"r":null,"lemma":null},{"ar":"أَنْعَمْتَ","tr":"anʿamta","gl":"You have bestowed (Your) Favors","glFr":"Tu as comblé","a":7,"r":"نعم","lemma":"أَنْعَمَ"},{"ar":"عَلَيْهِمْ","tr":"ʿalayhim","gl":"on them","glFr":"sur eux","a":7,"r":null,"lemma":null},{"ar":"غَيْرِ","tr":"ghayri","gl":"not (of)","glFr":"non pas","a":7,"r":"غير","lemma":"غَيْر"},{"ar":"ٱلْمَغْضُوبِ","tr":"l-maghḍūbi","gl":"those who earned (Your) wrath","glFr":"qui ont encouru la colère","a":7,"r":"غضب","lemma":"مَغْضُوب"},{"ar":"عَلَيْهِمْ","tr":"ʿalayhim","gl":"on themselves","glFr":"sur eux","a":7,"r":null,"lemma":null},{"ar":"وَلَا","tr":"walā","gl":"and not","glFr":"ni","a":7,"r":null,"lemma":null},{"ar":"ٱلضَّآلِّينَ","tr":"l-ḍālīna","gl":"(of) those who go astray","glFr":"des égarés","a":7,"r":"ضلل","lemma":"ضَآلّ"}],"roots":{"أله":{"letters":"أ ل ه","tl":"ʾ-l-h","n":2851,"senses":["To worship, serve, or adore as a deity","to be an object of worship, a god","to be confounded or perplexed, to seek refuge or protection","to devote oneself to religious acts","to protect, aid, or deliver from harm"],"sensesFr":["Adorer, servir comme une divinité","être un objet de culte, un dieu","être confondu ou perplexe, chercher refuge ou protection","se consacrer à des actes religieux","protéger, secourir, délivrer du mal"],"forms":[{"ar":"ٱللَّه","gl":"Allah","n":2699},{"ar":"إِلَٰه","gl":"god","n":147},{"ar":"ٱللَّهُمَّ","gl":"O Allah","n":5}],"occ":[{"ref":"2:7","ar":"خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰٓ أَبْصَـٰرِهِمْ غِشَـٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ","en":"Allah hath sealed their hearing and their hearts, and on their eyes there is a covering. Theirs will be an awful doom.","fr":"Allah, en effet, a apposé un sceau sur leurs cœurs et leur ouïe, tandis qu’un voile leur recouvre la vue. Ils sont donc voués à d’affreux tourments."},{"ref":"2:8","ar":"وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ","en":"And of mankind are some who say: We believe in Allah and the Last Day, when they believe not.","fr":"Il est des hommes qui prétendent croire en Allah et au Jour dernier alors qu’ils ne sont nullement croyants."},{"ref":"2:9","ar":"يُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ","en":"They think to beguile Allah and those who believe, and they beguile none save themselves; but they perceive not.","fr":"Ils pensent pouvoir tromper Allah et les croyants, mais ne trompent en réalité qu’eux-mêmes, sans en être conscients."}]},"حمد":{"letters":"ح م د","tl":"ḥ-m-d","n":63,"senses":["To praise, commend or approve","to be praiseworthy or commendable","to be angry","to recompense or requite","to affect or make a show of praise","to reproach for a favour","to burn or be vehement"],"sensesFr":["Louer, faire l’éloge ou approuver","être digne de louange ou d’éloge","se mettre en colère","récompenser ou rendre la pareille","affecter ou faire montre de louange","reprocher un bienfait","brûler ou être véhément"],"forms":[{"ar":"حَمْد","gl":"(the) praise","n":43},{"ar":"حَمِيد","gl":"the Praiseworthy","n":17},{"ar":"حَٰمِدُون","gl":"those who praise","n":1},{"ar":"مَّحْمُود","gl":"praiseworthy","n":1},{"ar":"يُحْمَدُ","gl":"they be praised","n":1}],"occ":[{"ref":"2:30","ar":"وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ","en":"And when thy Lord said unto the angels: Lo! I am about to place a viceroy in the earth, they said: Wilt thou place therein one who will do harm therein and will shed blood, while we, we hymn Thy praise and sanctify Thee? He said: Surely I know that which ye know not.","fr":"Mentionne ces paroles adressées par ton Seigneur aux anges : « Je vais installer un vicaire sur terre où ses descendants se succéderont de génération en génération. » Les anges s’étonnèrent : « Vas-tu y installer des êtres qui y répandront le mal et y feront couler le sang alors que, par nos louanges, nous célébrons Ta gloire et sanctifions Ton nom ? » Il dit : « Je sais des choses que vous ignorez. »"},{"ref":"2:267","ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَـٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ","en":"O ye who believe! Spend of the good things which ye have earned, and of that which We bring forth from the earth for you, and seek not the bad (with intent) to spend thereof (in charity) when ye would not take it for yourselves save with disdain; and know that Allah is Absolute, Owner of Praise.","fr":"Vous qui croyez ! Donnez en aumône de vos biens les plus précieux acquis honnêtement et des produits de la terre que Nous avons fait pousser pour vous. Ne choisissez pas ce que vous possédez de plus vil pour en faire l’aumône, alors que vous-mêmes ne l’accepteriez qu’à contrecœur. Et sachez qu’Allah peut parfaitement se passer de vos aumônes et qu’Il est digne de toutes les louanges."},{"ref":"3:188","ar":"لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ وَلَهُمْ عَذَابٌ أَلِيمٌ","en":"Think not that those who exult in what they have given, and love to be praised for what they have not done - Think not, they are in safety from the doom. A painful doom is theirs.","fr":"Ne crois surtout pas que ceux qui se réjouissent de leurs œuvres et qui aiment être loués pour ce qu’ils n’ont pas accompli, ne crois surtout pas qu’ils échapperont au châtiment. Ils sont, au contraire, voués à de douloureux tourments."}]},"دين":{"letters":"د ي ن","tl":"d-y-n","n":101,"senses":["To owe a debt, to be indebted","to lend, to give credit","to repay, to requite","to be obedient, to submit","a religion, a system of belief and practice","a reckoning, a judgment","a custom, a habit","to be abased, to be enslaved","to be accustomed, to be habituated","to be smitten by disease","to rule, to govern","to possess, to exercise authority."],"sensesFr":["Devoir une dette, être endetté","prêter, donner à crédit","rembourser, rétribuer","être obéissant, se soumettre","une religion, un système de croyance et de pratique","un compte, un jugement","une coutume, une habitude","être abaissé, être asservi","être accoutumé, être habitué","être frappé par la maladie","régir, gouverner","posséder, exercer l'autorité."],"forms":[{"ar":"دِين","gl":"the religion","n":92},{"ar":"دَيْن","gl":"any debt","n":5},{"ar":"مَدِينِين","gl":"surely be brought to Judgment","n":2},{"ar":"تَدَايَن","gl":"you contract with one another","n":1},{"ar":"يَدِينُ","gl":"they acknowledge","n":1}],"occ":[{"ref":"2:132","ar":"وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَـٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ","en":"The same did Abraham enjoin upon his sons, and also Jacob, (saying): O my sons! Lo! Allah hath chosen for you the (true) religion; therefore die not save as men who have surrendered (unto Him).","fr":"Abraham exhorta également ses fils à se soumettre à Allah - comme le fit Jacob avec les siens - disant : « Mes fils ! Allah a choisi pour vous cette religion. Que la mort ne vous prenne donc qu’en état de totale soumission. »"},{"ref":"2:193","ar":"وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِينَ","en":"And fight them until persecution is no more, and religion is for Allah. But if they desist, then let there be no hostility except against wrong-doers.","fr":"Combattez-les jusqu’à ce que nul ne soit persécuté pour sa foi et que le culte soit exclusivement voué à Allah. S’ils cessent toute hostilité, alors ne vous attaquez qu’à ceux d’entre eux qui agissent avec iniquité."},{"ref":"2:217","ar":"يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ وَلَا يَزَالُونَ يُقَـٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَـٰعُوا۟ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَـٰٓئِكَ حَبِطَتْ أَعْمَـٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ هُمْ فِيهَا خَـٰلِدُونَ","en":"They question thee (O Muhammad) with regard to warfare in the sacred month. Say: Warfare therein is a great (transgression), but to turn (men) from the way of Allah, and to disbelieve in Him and in the Inviolable Place of Worship, and to expel His people thence, is a greater with Allah; for persecution is worse than killing. And they will not cease from fighting against you till they have made you renegades from your religion, if they can. And whoso becometh a renegade and dieth in his disbelief: such are they whose works have fallen both in the world and the Hereafter. Such are rightful owners of the Fire: they will abide therein.","fr":"Ils t’interrogent au sujet des mois sacrés, s’il est permis d’y engager les combats. Dis : « Y combattre constitue un grave péché, mais plus grave encore pour Allah est de détourner les hommes de Sa voie, de ne pas croire en Lui, d’interdire l’accès à la Mosquée sacrée et d’en expulser les habitants. » Les persécutions que les idolâtres font subir aux croyants sont plus graves que les combats qui leur sont livrés et qui s’accompagnent nécessairement de morts. Ils ne cesseront, en effet, de vous combattre jusqu’à vous faire renier, s’ils le peuvent, votre religion. Or, quiconque parmi vous abjure la foi et meurt en mécréant perdra le bénéfice de ses œuvres ici-bas et dans l’au-delà, et est voué au feu de l’Enfer où il demeurera pour l’éternité."}]},"ربب":{"letters":"ر ب ب","tl":"r-b-b","n":980,"senses":["To be lord, master, or possessor","to own, rule, or govern","to rear, foster, and bring to maturity","to increase, complete, and put in right order","to season, preserve, and make good."],"sensesFr":["Être seigneur, maître ou possesseur","posséder, régir ou gouverner","élever, nourrir et amener à maturité","augmenter, parfaire et mettre en bon ordre","assaisonner, conserver et rendre bon."],"forms":[{"ar":"رَبّ","gl":"your Lord","n":975},{"ar":"رَبَّٰنِيِّن","gl":"the Rabbis","n":3},{"ar":"رَبَٰٓئِب","gl":"your step daughters","n":1},{"ar":"رِبِّيُّون","gl":"(were) religious scholars","n":1}],"occ":[{"ref":"2:5","ar":"أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","en":"These depend on guidance from their Lord. These are the successful.","fr":"Voilà ceux qui sont guidés par leur Seigneur, voilà les bienheureux."},{"ref":"2:21","ar":"يَـٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ","en":"O mankind! worship your Lord, Who hath created you and those before you, so that ye may ward off (evil).","fr":"Ô hommes ! Adorez votre Seigneur - qui vous a créés vous et vos devanciers - afin de vous préserver de Son châtiment."},{"ref":"2:26","ar":"إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَـٰسِقِينَ","en":"Lo! Allah disdaineth not to coin the similitude even of a gnat. Those who believe know that it is the truth from their Lord; but those who disbelieve say: What doth Allah wish (to teach) by such a similitude? He misleadeth many thereby, and He guideth many thereby; and He misleadeth thereby only miscreants;","fr":"Allah ne se gêne pas de proposer en parabole un moustique ou quelque chose de plus insignifiant. Les croyants savent d’ailleurs que cette parabole émane bien de leur Seigneur. Quant aux mécréants, ils disent : « Que peut bien vouloir signifier Allah par une telle parabole ? » Par elle, nombreux sont ceux qu’Il égare et par elle, nombreux ceux qu’Il guide. Mais Il n’égare, par de telles paraboles, que ceux qui Lui refusent obéissance,"}]},"رحم":{"letters":"ر ح م","tl":"r-ḥ-m","n":339,"senses":["To be tender-hearted, to show mercy and compassion","to pardon and forgive","the womb, the place of origin and the tie of kinship","to be connected by relationship","to have a complaint of the womb after birth"],"sensesFr":["Être compatissant, faire preuve de miséricorde et de pitié","pardonner et absoudre","la matrice, le lieu d'origine et le lien de parenté","être uni par la parenté","souffrir d'une affection de la matrice après l'enfantement"],"forms":[{"ar":"رَّحِيم","gl":"Most Merciful","n":116},{"ar":"رَحْمَة","gl":"mercy","n":114},{"ar":"رَّحْمَٰن","gl":"the Most Gracious","n":57},{"ar":"رَّحِمَ","gl":"receive mercy","n":28},{"ar":"أَرْحَام","gl":"the wombs","n":12},{"ar":"رَّٰحِمِين","gl":"(of) those who show mercy","n":6},{"ar":"أَرْحَم","gl":"(are) the Most Merciful","n":4},{"ar":"مَرْحَمَة","gl":"to compassion","n":1},{"ar":"رُحْم","gl":"(in) affection","n":1}],"occ":[{"ref":"2:37","ar":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتٍ فَتَابَ عَلَيْهِ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","en":"Then Adam received from his Lord words (of revelation), and He relented toward him. Lo! He is the relenting, the Merciful.","fr":"Adam prononça alors certaines paroles inspirées par son Seigneur qui accepta son repentir. C’est Lui, en effet, le Très Miséricordieux, Celui qui accepte toujours le repentir de Ses serviteurs."},{"ref":"2:54","ar":"وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","en":"And when Moses said unto his people: O my people! Ye have wronged yourselves by your choosing of the calf (for worship) so turn in penitence to your Creator, and kill (the guilty) yourselves. That will be best for you with your Creator and He will relent toward you. Lo! He is the Relenting, the Merciful.","fr":"Et lorsque Moïse dit à son peuple : « Mon peuple ! Vous avez été injustes envers vous-mêmes en vouant un culte au Veau. Revenez donc à votre Créateur en tuant vous-mêmes les coupables. Voilà qui est préférable pour vous et plus à même de satisfaire votre Créateur. » Le Seigneur agréa alors votre repentir. C’est Lui le Très Miséricordieux, Celui qui accepte toujours le repentir de Ses serviteurs."},{"ref":"2:64","ar":"ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَـٰسِرِينَ","en":"Then, even after that, ye turned away, and if it had not been for the grace of Allah and His mercy ye had been among the losers.","fr":"Mais vous vous êtes ensuite détournés, comportement qui, sans la grâce et la miséricorde d’Allah, aurait provoqué votre perte."}]},"سمو":{"letters":"س م و","tl":"s-m-w","n":381,"senses":["To be high, lofty, or elevated","to rise, to ascend","to name, to call by a name","to be noble or exalted in rank","to vie or compete for superiority","to hunt or pursue game","to be fixed or appointed"],"sensesFr":["Être haut, élevé, sublime","s'élever, monter","nommer, désigner par un nom","être noble ou de rang élevé","rivaliser, lutter pour la supériorité","chasser, poursuivre le gibier","être fixé, déterminé"],"forms":[{"ar":"سَمَآء","gl":"the heavens","n":310},{"ar":"ٱسْم","gl":"(the) name","n":39},{"ar":"مُّسَمًّى","gl":"appointed","n":21},{"ar":"سَمَّىٰ","gl":"[I] (have) named her","n":8},{"ar":"سَمِيّ","gl":"(this) name","n":2},{"ar":"تَسْمِيَة","gl":"name(s)","n":1}],"occ":[{"ref":"2:19","ar":"أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَـٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَـٰفِرِينَ","en":"Or like a rainstorm from the sky, wherein is darkness, thunder and the flash of lightning. They thrust their fingers in their ears by reason of the thunder-claps, for fear of death, Allah encompasseth the disbelievers (in His guidance, His omniscience and His omnipotence).","fr":"Ou à l’image d’hommes qui, sous une pluie battante accompagnée de ténèbres, de tonnerre et d’éclairs, se bouchent les oreilles, terrorisés par le fracas de la foudre et à l’idée de mourir foudroyés. Allah cerne de toutes parts les mécréants."},{"ref":"2:22","ar":"ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ","en":"Who hath appointed the earth a resting-place for you, and the sky a canopy; and causeth water to pour down from the sky, thereby producing fruits as food for you. And do not set up rivals to Allah when ye know (better).","fr":"C’est Lui qui, pour vous, a fait de la terre une couche et du ciel un toit, et qui fait descendre du ciel une eau par laquelle Il fait pousser toutes les variétés de fruits dont vous vous nourrissez. Gardez-vous donc d’associer de fausses divinités au culte d’Allah alors que vous savez."},{"ref":"2:29","ar":"هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَـٰوَٰتٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ","en":"He it is Who created for you all that is in the earth. Then turned He to the heaven, and fashioned it as seven heavens. And He is knower of all things.","fr":"C’est Lui qui, dans Sa science infinie, a créé pour vous tout ce qui se trouve sur terre avant de procéder à la création du Ciel dont Il a fait sept cieux parfaitement constitués."}]},"صرط":{"letters":"ص ر ط","tl":"ṣ-r-ṭ","n":45,"senses":["to be a clear, defined way","to be a path that guides and directs","to be a bridge, narrow and perilous, over an abyss","to be a course one must follow"],"sensesFr":["être un chemin clair et défini","être une voie qui guide et dirige","être un passage étroit et périlleux","être une trajectoire à suivre"],"forms":[{"ar":"صِرَٰط","gl":"a path","n":45}],"occ":[{"ref":"2:142","ar":"سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","en":"The foolish of the people will say: What hath turned them from the qiblah which they formerly observed? Say: Unto Allah belong the East and the West. He guideth whom He will unto a straight path.","fr":"Les ignorants diront : « Qu’est-ce qui a bien pu les détourner de la direction dans laquelle ils s’orientaient en prière ? » Dis : « Allah est le Maître du Levant et du Couchant. Il guide qui Il veut vers le droit chemin. »"},{"ref":"2:213","ar":"كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَـٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ بَغْيًۢا بَيْنَهُمْ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ","en":"Mankind were one community, and Allah sent (unto them) prophets as bearers of good tidings and as warners, and revealed therewith the Scripture with the truth that it might judge between mankind concerning that wherein they differed. And only those unto whom (the Scripture) was given differed concerning it, after clear proofs had come unto them, through hatred one of another. And Allah by His Will guided those who believe unto the truth of that concerning which they differed. Allah guideth whom He will unto a straight path.","fr":"Les hommes ne professaient à l’origine qu’une seule religion. Allah a alors suscité les prophètes pour leur annoncer la bonne nouvelle du Paradis et les mettre en garde contre l’Enfer, et a révélé à Ses Messagers la parole de vérité afin de trancher leurs différends. Or, ce sont ceux-là mêmes auxquels la vérité a été annoncée qui, poussés par la jalousie, se sont opposés après avoir pourtant reçu toutes les preuves. Allah, par Sa grâce, a alors guidé les croyants vers la vérité à propos de laquelle les autres nations se sont opposées. Allah guide qui Il veut vers le droit chemin."},{"ref":"3:51","ar":"إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَـٰذَا صِرَٰطٌ مُّسْتَقِيمٌ","en":"Lo! Allah is my Lord and your Lord, so worship Him. That is a straight path.","fr":"Allah, en vérité, est mon Seigneur et le vôtre, auquel vous devez un culte exclusif et sincère. Telle est la voie du salut. »"}]},"ضلل":{"letters":"ض ل ل","tl":"ḍ-l-l","n":191,"senses":["To lose the way, to stray, to be lost","to cause to lose the way, to mislead, to lead astray","to be hidden, to vanish, to perish","to forget, to be absent from memory","to be confounded, to be perplexed","to be futile, to come to nothing"],"sensesFr":["Perdre le chemin, s'égarer, être perdu","faire perdre le chemin, égarer, induire en erreur","être caché, disparaître, périr","oublier, être absent de la mémoire","être confondu, être perplexe","être vain, n'aboutir à rien"],"forms":[{"ar":"أَضَلَّ","gl":"Allah lets go astray","n":64},{"ar":"ضَلَّ","gl":"lost","n":53},{"ar":"ضَلَٰل","gl":"error","n":38},{"ar":"ضَآلّ","gl":"those who are astray","n":14},{"ar":"أَضَلّ","gl":"(is) more astray","n":9},{"ar":"ضَلَٰلَة","gl":"[the] astraying","n":9},{"ar":"مُّضِلّ","gl":"the misleaders","n":3},{"ar":"تَضْلِيل","gl":"astray","n":1}],"occ":[{"ref":"2:16","ar":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ","en":"These are they who purchase error at the price of guidance, so their commerce doth not prosper, neither are they guided.","fr":"Voilà ceux qui ont préféré, au droit chemin, la voie de l’égarement et qui courent à leur perte pour ce choix inconséquent."},{"ref":"2:26","ar":"إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَـٰسِقِينَ","en":"Lo! Allah disdaineth not to coin the similitude even of a gnat. Those who believe know that it is the truth from their Lord; but those who disbelieve say: What doth Allah wish (to teach) by such a similitude? He misleadeth many thereby, and He guideth many thereby; and He misleadeth thereby only miscreants;","fr":"Allah ne se gêne pas de proposer en parabole un moustique ou quelque chose de plus insignifiant. Les croyants savent d’ailleurs que cette parabole émane bien de leur Seigneur. Quant aux mécréants, ils disent : « Que peut bien vouloir signifier Allah par une telle parabole ? » Par elle, nombreux sont ceux qu’Il égare et par elle, nombreux ceux qu’Il guide. Mais Il n’égare, par de telles paraboles, que ceux qui Lui refusent obéissance,"},{"ref":"2:108","ar":"أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَـٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","en":"Or would ye question your messenger as Moses was questioned aforetime? He who chooseth disbelief instead of faith, verily he hath gone astray from a plain road.","fr":"Voulez-vous harceler de questions votre Messager comme Moïse l’a été avant lui ? Quiconque échange la foi contre l’impiété s’est, en vérité, écarté du droit chemin."}]},"عبد":{"letters":"ع ب د","tl":"ʿ-b-d","n":275,"senses":["To serve, worship, or adore a deity","to render religious service","to obey with humility and submission","to be a slave or servant, whether of God or of a false master","to be in a state of servitude or bondage","to be subdued, tamed, or made tractable","to be angry, disdainful, or scornful","to be covetous or cling inseparably","to be fatigued, to perish, or to stop","to be affected with mange or scab","to be refractory or difficult to manage","to be a human being, as a bondman to the Creator","to be ignoble or base-born","to be a road beaten and made even","to be a stone for pounding perfume","to be a short broad blade","to be a certain sweet-smelling plant."],"sensesFr":["Servir, adorer ou vénérer une divinité","rendre un culte religieux","obéir avec humilité et soumission","être un esclave ou un serviteur, de Dieu ou d’un maître faux","être dans un état de servitude ou d’asservissement","être dompté, apprivoisé ou rendu docile","être en colère, dédaigneux ou méprisant","être avide ou s’attacher inséparablement","être fatigué, périr ou s’arrêter","être atteint de gale ou de teigne","être rétif ou difficile à maîtriser","être un être humain, comme assujetti au Créateur","être ignoble ou de basse naissance","être une route foulée et aplanie","être une pierre à broyer les parfums","être une lame courte et large","être une plante odorante particulière."],"forms":[{"ar":"عَبْد","gl":"His slaves","n":131},{"ar":"عَبَدَ","gl":"worship","n":122},{"ar":"عَابِد","gl":"(are) worshippers","n":11},{"ar":"عِبَادَت","gl":"His worship","n":9},{"ar":"عَٰبِدَٰت","gl":"who worship","n":1},{"ar":"عَبَّد","gl":"you have enslaved","n":1}],"occ":[{"ref":"2:21","ar":"يَـٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ","en":"O mankind! worship your Lord, Who hath created you and those before you, so that ye may ward off (evil).","fr":"Ô hommes ! Adorez votre Seigneur - qui vous a créés vous et vos devanciers - afin de vous préserver de Son châtiment."},{"ref":"2:23","ar":"وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ","en":"And if ye are in doubt concerning that which We reveal unto Our slave (Muhammad), then produce a surah of the like thereof, and call your witness beside Allah if ye are truthful.","fr":"Si vous avez des doutes au sujet de ce que Nous avons révélé à notre serviteur, alors produisez une sourate identique, en vous aidant des divinités que vous adorez en dehors d’Allah, si vous dites la vérité."},{"ref":"2:83","ar":"وَإِذْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ","en":"And (remember) when We made a covenant with the Children of Israel, (saying): Worship none save Allah (only), and be good to parents and to kindred and to orphans and the needy, and speak kindly to mankind; and establish worship and pay the poor-due. Then, after that, ye slid back, save a few of you, being averse.","fr":"Rappelez-vous, fils d’Israël, lorsque Nous avons pris de vous l’engagement de n’adorer qu’Allah, de bien traiter vos père et mère, vos proches parents, les orphelins et les nécessiteux, d’adresser de bonnes paroles aux gens, d’accomplir la prière et de vous acquitter de l’aumône. Mais vous avez, à l’exception d’un petit nombre d’entre vous, tourné le dos à vos engagements."}]},"علم":{"letters":"ع ل م","tl":"ʿ-l-m","n":854,"senses":["To know, to have knowledge of, to be acquainted with","to be aware, to perceive, to understand","to be certain, to be sure","to be learned, to be versed in a subject","to teach, to instruct, to impart knowledge","to mark, to make a sign, to distinguish by a token","to be a sign, to serve as a guidepost or landmark","a mark, a sign, a token, a banner","a mountain, a prominent feature","the world, the universe, all created beings","the learned, the scholars","the All-Knowing, the Omniscient, as an attribute of God."],"sensesFr":["Savoir, avoir connaissance de, être informé de","être conscient, percevoir, comprendre","être certain, être sûr","être savant, être versé dans une science","enseigner, instruire, transmettre un savoir","marquer, faire un signe, distinguer par un indice","être un signe, servir de repère ou de borne","une marque, un signe, un indice, un étendard","une montagne, un élément saillant du paysage","le monde, l'univers, l'ensemble des créatures","les savants, les érudits","le Très-Savant, l'Omniscient, attribut de Dieu."],"forms":[{"ar":"عَلِمَ","gl":"know","n":382},{"ar":"عَلِيم","gl":"(is) All-Knower","n":163},{"ar":"عِلْم","gl":"knowledge","n":105},{"ar":"عَٰلَمِين","gl":"(of) the worlds","n":73},{"ar":"أَعْلَم","gl":"(is) most knowing","n":49},{"ar":"عَلَّمَ","gl":"He taught","n":41},{"ar":"عَٰلِم","gl":"Knower","n":18},{"ar":"مَّعْلُوم","gl":"known","n":11},{"ar":"عَلَّٰم","gl":"(are the) Knower","n":4},{"ar":"أَعْلَٰم","gl":"like [the] mountains","n":2},{"ar":"مَّعْلُومَٰت","gl":"well known","n":2},{"ar":"يَتَعَلَّمُ","gl":"they learn","n":2},{"ar":"عَلَٰمَٰت","gl":"landmarks","n":1},{"ar":"مُعَلَّم","gl":"One taught","n":1}],"occ":[{"ref":"2:13","ar":"وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَـٰكِن لَّا يَعْلَمُونَ","en":"And when it is said unto them: believe as the people believe, they say: shall we believe as the foolish believe? are not they indeed the foolish? But they know not.","fr":"Exhortés à adhérer pleinement à la foi, à l’image des vrais croyants, ils disent : « Allons-nous croire comme ces ignorants ? » Ce sont pourtant eux, sans le savoir, qui sont ignorants."},{"ref":"2:22","ar":"ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ","en":"Who hath appointed the earth a resting-place for you, and the sky a canopy; and causeth water to pour down from the sky, thereby producing fruits as food for you. And do not set up rivals to Allah when ye know (better).","fr":"C’est Lui qui, pour vous, a fait de la terre une couche et du ciel un toit, et qui fait descendre du ciel une eau par laquelle Il fait pousser toutes les variétés de fruits dont vous vous nourrissez. Gardez-vous donc d’associer de fausses divinités au culte d’Allah alors que vous savez."},{"ref":"2:26","ar":"إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَـٰسِقِينَ","en":"Lo! Allah disdaineth not to coin the similitude even of a gnat. Those who believe know that it is the truth from their Lord; but those who disbelieve say: What doth Allah wish (to teach) by such a similitude? He misleadeth many thereby, and He guideth many thereby; and He misleadeth thereby only miscreants;","fr":"Allah ne se gêne pas de proposer en parabole un moustique ou quelque chose de plus insignifiant. Les croyants savent d’ailleurs que cette parabole émane bien de leur Seigneur. Quant aux mécréants, ils disent : « Que peut bien vouloir signifier Allah par une telle parabole ? » Par elle, nombreux sont ceux qu’Il égare et par elle, nombreux ceux qu’Il guide. Mais Il n’égare, par de telles paraboles, que ceux qui Lui refusent obéissance,"}]},"عون":{"letters":"ع و ن","tl":"ʿ-w-n","n":11,"senses":["To aid, help, assist","to seek aid, to call for help","aid, assistance, support","a helper, an assistant","to be of middle age, neither young nor old","the pubic hair"],"sensesFr":["Aider, secourir, assister","demander de l'aide, appeler au secours","aide, assistance, soutien","un aide, un assistant","être d'âge mûr, ni jeune ni vieux","le poil pubien"],"forms":[{"ar":"ٱسْتَعِينُ","gl":"Seek help","n":4},{"ar":"أَعَانَ","gl":"assist me","n":2},{"ar":"مُسْتَعَان","gl":"(is) the One sought for help","n":2},{"ar":"تَعَاوَنُ","gl":"help one another","n":2},{"ar":"عَوَان","gl":"middle aged","n":1}],"occ":[{"ref":"2:45","ar":"وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَـٰشِعِينَ","en":"Seek help in patience and prayer; and truly it is hard save for the humble-minded,","fr":"Armez-vous de patience et aidez-vous de la prière. Celle-ci représente cependant une lourde obligation, sauf pour les êtres humbles"},{"ref":"2:68","ar":"قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ","en":"They said: Pray for us unto thy Lord that He make clear to us what (cow) she is. (Moses) answered: Lo! He saith, Verily she is a cow neither with calf nor immature; (she is) between the two conditions; so do that which ye are commanded.","fr":"Ils demandèrent : « Prie pour nous ton Seigneur de nous indiquer à quoi elle doit ressembler. » Il répondit : « Allah dit qu’elle ne doit être ni trop vieille, ni trop jeune, mais d’un âge intermédiaire. Exécutez donc l’ordre qui vous est donné. »"},{"ref":"2:153","ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ","en":"O ye who believe! Seek help in steadfastness and prayer. Lo! Allah is with the steadfast.","fr":"Vous qui croyez ! Armez-vous de patience et aidez-vous de la prière. Allah est avec ceux qui font preuve de constance."}]},"غضب":{"letters":"غ ض ب","tl":"gh-ḍ-b","n":24,"senses":["To be angry, a heat that rises and demands redress","to be red and dense, like a boiling pot or a deep ember","to be hard and unyielding, as a fixed rock","to be stern and malignant, like a serpent's gaze","to break off in anger, quitting a person or a place"],"sensesFr":["Être en colère, une chaleur qui monte et exige réparation","être rouge et dense, comme un pot qui bout ou une braise profonde","être dur et inflexible, comme un roc fixe","être sévère et malveillant, tel le regard d'un serpent","rompre dans la colère, quitter une personne ou un lieu"],"forms":[{"ar":"غَضَب","gl":"wrath","n":14},{"ar":"غَضِبَ","gl":"will fall the wrath","n":6},{"ar":"غَضْبَٰن","gl":"angry","n":2},{"ar":"مَغْضُوب","gl":"those who earned (Your) wrath","n":1},{"ar":"مُغَٰضِب","gl":"(while) angry","n":1}],"occ":[{"ref":"2:61","ar":"وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ","en":"And when ye said: O Moses! We are weary of one kind of food; so call upon thy Lord for us that He bring forth for us of that which the earth groweth - of its herbs and its cucumbers and its corn and its lentils and its onions. He said: Would ye exchange that which is higher for that which is lower? Go down to settled country, thus ye shall get that which ye demand. And humiliation and wretchedness were stamped upon them and they were visited with wrath from Allah. That was because they disbelieved in Allah's revelations and slew the prophets wrongfully. That was for their disobedience and transgression.","fr":"Mais vous avez dit : « Moïse ! Nous ne pouvons supporter plus longtemps de consommer tous les jours les mêmes aliments. Demande donc à ton Seigneur de faire pousser pour nous des légumes, des concombres, de l’ail, des lentilles ou des oignons. » Il répondit : « Voulez-vous vraiment substituer ces nourritures grossières à des aliments de meilleure qualité ? Descendez donc dans n’importe quelle cité, vous y trouverez ce que vous réclamez ! » Ils furent donc couverts d’opprobre, plongés dans la misère et poursuivis par la colère d’Allah pour avoir, poussés par leur goût de la désobéissance et de la transgression, renié les signes d’Allah et tué injustement les prophètes."},{"ref":"2:90","ar":"بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ","en":"Evil is that for which they sell their souls: that they should disbelieve in that which Allah hath revealed, grudging that Allah should reveal of His bounty unto whom He will of His slaves. They have incurred anger upon anger. For disbelievers is a shameful doom.","fr":"Bien mauvais choix que celui de ces hommes qui ont rejeté le Livre révélé par Allah, jaloux que le Seigneur choisisse, par un effet de Sa grâce, de confier Sa révélation à d’autres qu’eux. Ils ont donc doublement mérité la colère d’Allah. Les mécréants sont voués à un châtiment humiliant."},{"ref":"3:112","ar":"ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ","en":"Ignominy shall be their portion wheresoever they are found save (where they grasp) a rope from Allah and a rope from men. They have incurred anger from their Lord, and wretchedness is laid upon them. That is because they used to disbelieve the revelations of Allah, and slew the prophets wrongfully. That is because they were rebellious and used to transgress.","fr":"Où qu’ils se trouvent, ils sont couverts d’humiliation, à moins qu’ils ne se placent sous la protection d’Allah ou sous la protection d’une autre nation. Ils seront à jamais poursuivis par la colère d’Allah et plongés dans la misère pour avoir, poussés par leur goût de la désobéissance et de la transgression, renié les signes d’Allah et tué injustement les prophètes."}]},"غير":{"letters":"غ ي ر","tl":"gh-y-r","n":154,"senses":["To alter or change a thing from its former state","to exchange one thing for another","to be other than, to differ from","to be jealous, to guard against suspicion","to provide for, to benefit with abundance"],"sensesFr":["Changer une chose de son état antérieur","échanger une chose contre une autre","être autre que, différer de","être jaloux, se garder du soupçon","pourvoir, bénéficier d'abondance"],"forms":[{"ar":"غَيْر","gl":"without","n":147},{"ar":"يُغَيِّرُ","gl":"they change","n":4},{"ar":"مُغَيِّر","gl":"One Who changes","n":1},{"ar":"مُغِيرَٰت","gl":"the chargers","n":1},{"ar":"يَتَغَيَّرْ","gl":"changes","n":1}],"occ":[{"ref":"2:59","ar":"فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ","en":"But those who did wrong changed the word which had been told them for another saying, and We sent down upon the evil-doers wrath from heaven for their evil-doing.","fr":"Mais ceux d’entre eux qui étaient injustes ont préféré d’autres paroles à celles qui leur avaient été indiquées. Pour prix de leur désobéissance, Nous avons fait fondre sur eux un terrible châtiment venant du ciel."},{"ref":"2:61","ar":"وَإِذْ قُلْتُمْ يَـٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَـٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ","en":"And when ye said: O Moses! We are weary of one kind of food; so call upon thy Lord for us that He bring forth for us of that which the earth groweth - of its herbs and its cucumbers and its corn and its lentils and its onions. He said: Would ye exchange that which is higher for that which is lower? Go down to settled country, thus ye shall get that which ye demand. And humiliation and wretchedness were stamped upon them and they were visited with wrath from Allah. That was because they disbelieved in Allah's revelations and slew the prophets wrongfully. That was for their disobedience and transgression.","fr":"Mais vous avez dit : « Moïse ! Nous ne pouvons supporter plus longtemps de consommer tous les jours les mêmes aliments. Demande donc à ton Seigneur de faire pousser pour nous des légumes, des concombres, de l’ail, des lentilles ou des oignons. » Il répondit : « Voulez-vous vraiment substituer ces nourritures grossières à des aliments de meilleure qualité ? Descendez donc dans n’importe quelle cité, vous y trouverez ce que vous réclamez ! » Ils furent donc couverts d’opprobre, plongés dans la misère et poursuivis par la colère d’Allah pour avoir, poussés par leur goût de la désobéissance et de la transgression, renié les signes d’Allah et tué injustement les prophètes."},{"ref":"2:173","ar":"إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ","en":"He hath forbidden you only carrion, and blood, and swineflesh, and that which hath been immolated to (the name of) any other than Allah. But he who is driven by necessity, neither craving nor transgressing, it is no sin for him. Lo! Allah is Forgiving, Merciful.","fr":"Il vous a uniquement interdit la chair de la bête morte, le sang, la viande de porc et tout animal sacrifié aux fausses divinités. Celui, néanmoins, qui serait contraint d’en consommer, sans intention de transgresser et sans en abuser, ne commet aucun péché. Allah, en vérité, est Très Clément et Très Miséricordieux."}]},"قوم":{"letters":"ق و م","tl":"q-w-m","n":660,"senses":["To stand, to rise, to be upright","to remain, to abide, to endure","to establish, to set up, to make firm","to manage, to maintain, to take charge of","to be correct, to be straight, to be in order","a people, a community, a group bound by common standing","the standing up of the dead, the resurrection","value, worth, that which makes a thing stand as its equivalent."],"sensesFr":["Se tenir debout, se lever, être droit","demeurer, persister, subsister","établir, instituer, affermir","gérer, administrer, prendre en charge","être correct, être droit, être en ordre","un peuple, une communauté, un groupe lié par une condition commune","le relèvement des morts, la résurrection","la valeur, le prix, ce qui fait qu'une chose tient lieu d'une autre."],"forms":[{"ar":"قَوْم","gl":"a people","n":383},{"ar":"قِيَٰمَة","gl":"(of) the Resurrection","n":70},{"ar":"أَقَامَ","gl":"establish","n":54},{"ar":"مُّسْتَقِيم","gl":"straight","n":37},{"ar":"قَامَ","gl":"stand","n":33},{"ar":"قَآئِم","gl":"standing","n":17},{"ar":"مَقَام","gl":"a place","n":14},{"ar":"مُّقِيم","gl":"lasting","n":10},{"ar":"ٱسْتَقَٰمُ","gl":"stand firm","n":10},{"ar":"قَآئِمَة","gl":"standing","n":5},{"ar":"قَيِّم","gl":"the upright","n":5},{"ar":"أَقْوَم","gl":"more suitable","n":4},{"ar":"مُقَام","gl":"resting place","n":3},{"ar":"قَوَّٰمِين","gl":"(are) protectors","n":3},{"ar":"قَيُّوم","gl":"the Sustainer of all that exists","n":3},{"ar":"إِقَام","gl":"establishment","n":2},{"ar":"قَيِّمَة","gl":"correct","n":2},{"ar":"إِقَامَت","gl":"(of) your encampment","n":1},{"ar":"مُقَامَة","gl":"(of) Eternity","n":1},{"ar":"قَوَام","gl":"moderate","n":1},{"ar":"قِيَم","gl":"right","n":1},{"ar":"تَقْوِيم","gl":"mould","n":1}],"occ":[{"ref":"2:3","ar":"ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ","en":"Who believe in the Unseen, and establish worship, and spend of that We have bestowed upon them;","fr":"qui croient aux mystères, accomplissent la prière et offrent par charité une partie de ce que Nous leur avons accordé,"},{"ref":"2:20","ar":"يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَـٰرَهُمْ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَـٰرِهِمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","en":"The lightning almost snatcheth away their sight from them. As often as it flasheth forth for them they walk therein, and when it darkeneth against them they stand still. If Allah willed, He could destroy their hearing and their sight. Lo! Allah is able to do all things.","fr":"Peu s’en faut que l’éclair ne leur ravisse la vue. Chaque fois que celui-ci illumine le ciel, ils progressent à sa lumière, mais s’immobilisent dès qu’ils sont plongés dans l’obscurité. Allah, s’Il le voulait, pourrait les priver de l’ouïe et de la vue. Allah, en vérité, est Omnipotent."},{"ref":"2:43","ar":"وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ","en":"Establish worship, pay the poor-due, and bow your heads with those who bow (in worship).","fr":"Accomplissez la prière, acquittez-vous de l’aumône et inclinez-vous humblement avec les musulmans."}]},"ملك":{"letters":"م ل ك","tl":"m-l-k","n":206,"senses":["To possess, to own, to have power over","to rule, to exercise authority, to have dominion","to be a king or sovereign","to have the ability to command and forbid","to take possession by force","to be unable to restrain oneself from an action","an angel, a being of the unseen world","a kingdom, a realm","a slave, a bondman."],"sensesFr":["Posséder, être propriétaire, avoir pouvoir sur","régner, exercer l'autorité, avoir la souveraineté","être un roi ou un souverain","avoir la capacité de commander et d'interdire","s'emparer de force","ne pouvoir se retenir d'une action","un ange, un être du monde invisible","un royaume, un domaine","un esclave, un serf."],"forms":[{"ar":"مَلَك","gl":"the Angels","n":88},{"ar":"مُلْك","gl":"(is the) dominion","n":48},{"ar":"مَلَكَتْ","gl":"possess","n":44},{"ar":"مَلِك","gl":"the king","n":15},{"ar":"مَلَكُوت","gl":"the kingdom","n":4},{"ar":"مَٰلِك","gl":"(The) Master","n":3},{"ar":"مَٰلِك","gl":"O Malik","n":1},{"ar":"مَلِيك","gl":"a King","n":1},{"ar":"مَلْك","gl":"by our will","n":1},{"ar":"مَّمْلُوك","gl":"(who is) owned","n":1}],"occ":[{"ref":"2:30","ar":"وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ","en":"And when thy Lord said unto the angels: Lo! I am about to place a viceroy in the earth, they said: Wilt thou place therein one who will do harm therein and will shed blood, while we, we hymn Thy praise and sanctify Thee? He said: Surely I know that which ye know not.","fr":"Mentionne ces paroles adressées par ton Seigneur aux anges : « Je vais installer un vicaire sur terre où ses descendants se succéderont de génération en génération. » Les anges s’étonnèrent : « Vas-tu y installer des êtres qui y répandront le mal et y feront couler le sang alors que, par nos louanges, nous célébrons Ta gloire et sanctifions Ton nom ? » Il dit : « Je sais des choses que vous ignorez. »"},{"ref":"2:31","ar":"وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَـٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَـٰٓؤُلَآءِ إِن كُنتُمْ صَـٰدِقِينَ","en":"And He taught Adam all the names, then showed them to the angels, saying: Inform Me of the names of these, if ye are truthful.","fr":"Allah enseigna à Adam les noms de toutes choses avant de les présenter aux anges auxquels Il dit : « Indiquez-Moi leurs noms, si vous dites la vérité lorsque vous prétendez être supérieurs aux hommes. »"},{"ref":"2:34","ar":"وَإِذْ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَـٰفِرِينَ","en":"And when We said unto the angels: Prostrate yourselves before Adam, they fell prostrate, all save Iblis. He demurred through pride, and so became a disbeliever.","fr":"Lorsque Nous avons ordonné aux anges de se prosterner devant Adam, tous se sont exécutés, excepté Satan qui refusa par orgueil de se prosterner, se comportant en impie."}]},"نعم":{"letters":"ن ع م","tl":"n-ʿ-m","n":140,"senses":["To be soft, tender, and flourishing","to live in ease and plenty","to confer a benefit or favour","cattle as a source of wealth and ease","an affirmative particle","to be excellent or most excellent"],"sensesFr":["Être doux, tendre et florissant","vivre dans l’aisance et l’abondance","conférer un bienfait ou une faveur","le bétail comme source de richesse et de bien-être","particule affirmative","être excellent ou très bon"],"forms":[{"ar":"نِعْمَة","gl":"(the) Favor","n":50},{"ar":"نَّعَم","gl":"the cattle","n":33},{"ar":"نِعْمَ","gl":"an excellent","n":18},{"ar":"أَنْعَمَ","gl":"I bestowed","n":17},{"ar":"نَعِيم","gl":"(of) Delight","n":17},{"ar":"نَّعْمَة","gl":"pleasant things","n":2},{"ar":"نَعْمَآء","gl":"(of) favor","n":1},{"ar":"نَعَّمَ","gl":"favors him","n":1},{"ar":"نَّاعِمَة","gl":"(will be) joyful","n":1}],"occ":[{"ref":"2:40","ar":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّـٰىَ فَٱرْهَبُونِ","en":"O Children of Israel! Remember My favour wherewith I favoured you, and fulfil your (part of the) covenant, I shall fulfil My (part of the) covenant, and fear Me.","fr":"Fils d’Israël ! Souvenez-vous des bienfaits dont Je vous ai comblés et soyez fidèles à vos engagements contractés envers Moi, j’honorerai Mon engagement pris envers vous. C’est Moi seul que vous devez redouter."},{"ref":"2:47","ar":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ","en":"O Children of Israel! Remember My favour wherewith I favoured you and how I preferred you to (all) creatures.","fr":"Fils d’Israël ! Souvenez-vous des bienfaits dont Je vous ai pourvus et rappelez-vous que J’ai fait de vous Mon peuple élu."},{"ref":"2:122","ar":"يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَـٰلَمِينَ","en":"O Children of Israel! Remember My favour wherewith I favoured you and how I preferred you to (all) creatures.","fr":"Fils d’Israël ! Souvenez-vous des bienfaits dont Je vous ai pourvus et rappelez-vous que J’ai fait de vous Mon peuple élu."}]},"هدي":{"letters":"ه د ي","tl":"h-d-y","n":316,"senses":["To guide someone to the right path","to be guided aright","to follow a right course","to send a bride to her husband","to make a truce","a present or offering brought to a sacred place","a way or manner of proceeding","calmness of deportment"],"sensesFr":["Guider quelqu’un sur le droit chemin","être guidé droitement","suivre une voie droite","conduire la mariée chez son époux","conclure une trêve","un présent ou une offrande apportée à un lieu sacré","une manière ou une méthode d’agir","une conduite calme"],"forms":[{"ar":"هَدَى","gl":"guide","n":144},{"ar":"هُدًى","gl":"the guidance","n":85},{"ar":"ٱهْتَدَىٰ","gl":"(be) guided","n":40},{"ar":"مُّهْتَدُون","gl":"guided-ones","n":17},{"ar":"أَهْدَىٰ","gl":"better guided","n":7},{"ar":"هَاد","gl":"guide","n":7},{"ar":"هَدْي","gl":"the sacrificial animal","n":7},{"ar":"مُّهْتَد","gl":"the guided one","n":3},{"ar":"هَادِي","gl":"guide","n":2},{"ar":"هَدِيَّة","gl":"a gift","n":2},{"ar":"هَٰدِى","gl":"guide","n":1},{"ar":"مُهْتَدِى","gl":"(is) the guided one","n":1}],"occ":[{"ref":"2:2","ar":"ذَٰلِكَ ٱلْكِتَـٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ","en":"This is the Scripture whereof there is no doubt, a guidance unto those who ward off (evil).","fr":"Voici le Livre qui n’admet aucun doute et qui est un guide pour ceux qui craignent le Seigneur,"},{"ref":"2:5","ar":"أُو۟لَـٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","en":"These depend on guidance from their Lord. These are the successful.","fr":"Voilà ceux qui sont guidés par leur Seigneur, voilà les bienheureux."},{"ref":"2:16","ar":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ","en":"These are they who purchase error at the price of guidance, so their commerce doth not prosper, neither are they guided.","fr":"Voilà ceux qui ont préféré, au droit chemin, la voie de l’égarement et qui courent à leur perte pour ce choix inconséquent."}]},"يوم":{"letters":"ي و م","tl":"y-w-m","n":405,"senses":["To mark a span of time, from a single revolution of the sun to an epoch","to be the appointed time for an event or a reckoning","to be a day of conflict or trial","to recur day after day"],"sensesFr":["Désigner une durée, d’une révolution du soleil à une époque","être le moment fixé pour un événement ou un jugement","être un jour de combat ou d’épreuve","revenir jour après jour"],"forms":[{"ar":"يَوْم","gl":"(the) Day","n":405}],"occ":[{"ref":"2:8","ar":"وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ","en":"And of mankind are some who say: We believe in Allah and the Last Day, when they believe not.","fr":"Il est des hommes qui prétendent croire en Allah et au Jour dernier alors qu’ils ne sont nullement croyants."},{"ref":"2:48","ar":"وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَـٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ","en":"And guard yourselves against a day when no soul will in aught avail another, nor will intercession be accepted from it, nor will compensation be received from it, nor will they be helped.","fr":"Craignez le Jour où nul ne pourra rien pour son prochain, où nulle intercession ne sera acceptée sans l’autorisation d’Allah, où nul ne pourra racheter son âme et nul ne pourra être sauvé s’il meurt dans l’impiété."},{"ref":"2:62","ar":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَـٰرَىٰ وَٱلصَّـٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","en":"Lo! Those who believe (in that which is revealed unto thee, Muhammad), and those who are Jews, and Christians, and Sabaeans - whoever believeth in Allah and the Last Day and doeth right - surely their reward is with their Lord, and there shall no fear come upon them neither shall they grieve.","fr":"Les croyants, les juifs, les chrétiens, les sabéens, tous ceux qui auront cru en Allah et au Jour dernier, et accompli de bonnes actions, obtiendront leur récompense auprès de leur Seigneur et seront préservés de toute crainte et de toute affliction."}]}},"ayas":{"1":{"en":"In the name of Allah, the Beneficent, the Merciful.","fr":"Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux."},"2":{"en":"Praise be to Allah, Lord of the Worlds,","fr":"Louange à Allah, Seigneur de la Création,"},"3":{"en":"The Beneficent, the Merciful.","fr":"le Tout Miséricordieux, le Très Miséricordieux,"},"4":{"en":"Master of the Day of Judgment,","fr":"Maître souverain du Jour de la rétribution."},"5":{"en":"Thee (alone) we worship; Thee (alone) we ask for help.","fr":"C’est Toi seul que nous adorons et de Toi seul que nous implorons aide."},"6":{"en":"Show us the straight path,","fr":"Guide-nous dans le droit chemin,"},"7":{"en":"The path of those whom Thou hast favoured; Not the (path) of those who earn Thine anger nor of those who go astray.","fr":"chemin de ceux que Tu as comblés de Tes grâces, non celui des réprouvés, ni celui des égarés."}}},"prayer":{"1":[[["بِسْمِ","In (the) name"],["ٱللَّهِ","(of) Allah"],["ٱلرَّحْمَـٰنِ","the Most Gracious"],["ٱلرَّحِيمِ","the Most Merciful"]],[["ٱلْحَمْدُ","All praises and thanks"],["لِلَّهِ","(be) to Allah"],["رَبِّ","the Lord"],["ٱلْعَـٰلَمِينَ","of the universe"]],[["ٱلرَّحْمَـٰنِ","The Most Gracious"],["ٱلرَّحِيمِ","the Most Merciful"]],[["مَـٰلِكِ","(The) Master"],["يَوْمِ","(of the) Day"],["ٱلدِّينِ","(of the) Judgment"]],[["إِيَّاكَ","You Alone"],["نَعْبُدُ","we worship"],["وَإِيَّاكَ","and You Alone"],["نَسْتَعِينُ","we ask for help"]],[["ٱهْدِنَا","Guide us"],["ٱلصِّرَٰطَ","(to) the path"],["ٱلْمُسْتَقِيمَ","the straight"]],[["صِرَٰطَ","(The) path"],["ٱلَّذِينَ","(of) those"],["أَنْعَمْتَ","You have bestowed (Your) Favors"],["عَلَيْهِمْ","on them"],["غَيْرِ","not (of)"],["ٱلْمَغْضُوبِ","those who earned (Your) wrath"],["عَلَيْهِمْ","on themselves"],["وَلَا","and not"],["ٱلضَّآلِّينَ","(of) those who go astray"]]],"2":[[["الٓمٓ","Alif Laam Meem"]],[["ذَٰلِكَ","That"],["ٱلْكِتَـٰبُ","(is) the book"],["لَا","no"],["رَيْبَ","doubt"],["فِيهِ","in it"],["هُدًى","a Guidance"],["لِّلْمُتَّقِينَ","for the God-conscious"]],[["ٱلَّذِينَ","Those who"],["يُؤْمِنُونَ","believe"],["بِٱلْغَيْبِ","in the unseen"],["وَيُقِيمُونَ","and establish"],["ٱلصَّلَوٰةَ","the prayer"],["وَمِمَّا","and out of what"],["رَزَقْنَـٰهُمْ","We have provided them"],["يُنفِقُونَ","they spend"]],[["وَٱلَّذِينَ","And those who"],["يُؤْمِنُونَ","believe"],["بِمَآ","in what"],["أُنزِلَ","(is) sent down"],["إِلَيْكَ","to you"],["وَمَآ","and what"],["أُنزِلَ","was sent down"],["مِن","from"],["قَبْلِكَ","before you"],["وَبِٱلْـَٔاخِرَةِ","and in the Hereafter"],["هُمْ","they"],["يُوقِنُونَ","firmly believe"]],[["أُو۟لَـٰٓئِكَ","Those"],["عَلَىٰ","(are) on"],["هُدًى","Guidance"],["مِّن","from"],["رَّبِّهِمْ","their Lord"],["وَأُو۟لَـٰٓئِكَ","and those "],["هُمُ","they"],["ٱلْمُفْلِحُونَ","(are) the successful ones"]]],"103":[[["وَٱلْعَصْرِ","By the time"]],[["إِنَّ","Indeed"],["ٱلْإِنسَـٰنَ","mankind"],["لَفِى","(is) surely, in"],["خُسْرٍ","loss"]],[["إِلَّا","Except"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ","righteous deeds"],["وَتَوَاصَوْا۟","and enjoin (each other)"],["بِٱلْحَقِّ","to the truth"],["وَتَوَاصَوْا۟","and enjoin (each other)"],["بِٱلصَّبْرِ","to [the] patience"]]],"108":[[["إِنَّآ","Indeed, We"],["أَعْطَيْنَـٰكَ","We have given you"],["ٱلْكَوْثَرَ","Al-Kauthar"]],[["فَصَلِّ","So pray"],["لِرَبِّكَ","to your Lord"],["وَٱنْحَرْ","and sacrifice"]],[["إِنَّ","Indeed"],["شَانِئَكَ","your enemy "],["هُوَ","he (is)"],["ٱلْأَبْتَرُ","the one cut off"]]],"112":[[["قُلْ","Say"],["هُوَ","He"],["ٱللَّهُ","(is) Allah"],["أَحَدٌ","the One"]],[["ٱللَّهُ","Allah"],["ٱلصَّمَدُ","the Eternal, the Absolute"]],[["لَمْ","Not"],["يَلِدْ","He begets"],["وَلَمْ","and not"],["يُولَدْ","He is begotten"]],[["وَلَمْ","And not"],["يَكُن","is"],["لَّهُۥ","for Him"],["كُفُوًا","equivalent"],["أَحَدٌۢ","any [one]"]]]}};
